3620	/****************************************************************************
3621	 * Name: yuv_to_rgb
3622	 *
3623	 * Description:
3624	 *   Shared YUV→RGB helper for dump diagnostics.
3625	 *   Input: Y, U, V as raw bytes (0-255).
3626	 *   Output: r, g, b clamped to 0-255.
3627	 *
3628	 ****************************************************************************/
3629	
3630	static void yuv_to_rgb(uint8_t y, uint8_t u, uint8_t v,
3631	                        int *r, int *g, int *b)
3632	{
3633	  int yi = (int)y;
3634	  int cb = (int)u - 128;
3635	  int cr = (int)v - 128;
3636	
3637	  *r = yi + cr + (cr * 51 / 128);
3638	  *g = yi - (cb * 28 / 81) - (cr * 365 / 512);
3639	  *b = yi + cb + (cb * 99 / 128);
3640	
3641	  if (*r < 0) *r = 0;  if (*r > 255) *r = 255;
3642	  if (*g < 0) *g = 0;  if (*g > 255) *g = 255;
3643	  if (*b < 0) *b = 0;  if (*b > 255) *b = 255;
3644	}
