/****************************************************************************
 * Name: bk7258_camera_still
 *
 * Description:
 *   Freeze-frame diagnostic: capture exactly 1 frame, stop DVP immediately
 *   (freeze PSRAM buffer), then downscale + blit to LCD.  Screen stays
 *   frozen — no loop, no warm-up.
 *
 *   Purpose: determine if preview "花屏" is caused by DVP-write vs
 *   display-read race condition (ping-pong ownership) or by format/
 *   downscale bug.
 *
 *   Diagnostic key:
 *     frozen frame clean  → race condition (DVP overwrites during blit)
 *     frozen frame garbled → format/downscale/stride issue
 *
 * Prerequisites:
 *   camera init + camera buf.
 *
 ****************************************************************************/

int bk7258_camera_still(int panel)
{
  int ret;
  int timeout_ms;
  uint32_t frame_start;
  uint32_t frame_addr;
  volatile uint8_t *buf;
  volatile uint8_t *preview_buf;
  int buf_idx;
  int i;

  preview_buf = (volatile uint8_t *)PREVIEW_ADDR;

  /* Check DVP pins are configured */

  if (!g_dvp_pins_configed)
    {
      syslog(LOG_ERR,
             "[camera] DVP pins not configured — run 'camera init' first\n");
      return -ENODEV;
    }

  /* Check frame buffers allocated */

  if (!g_framebuf_allocated)
    {
      syslog(LOG_ERR,
             "[camera] Frame buffers not allocated — run 'camera buf' first\n");
      return -ENOMEM;
    }

  /* Configure DVP controller — output to buf[0] (single buffer, no ping-pong) */

  ret = dvp_ctrl_config((uint32_t)(uintptr_t)g_camera_buf[0]);
  if (ret < 0)
    {
      syslog(LOG_ERR, "[camera] still: DVP ctrl config failed: %d\n", ret);
      goto done;
    }

  /* Attach interrupt handler */

  ret = dvp_irq_attach();
  if (ret < 0)
    {
      syslog(LOG_ERR, "[camera] still: DVP IRQ attach failed: %d\n", ret);
      goto cleanup_ctrl;
    }

  /* Do NOT set g_stream_active — single-buffer mode, no ping-pong.
   * The ISR will increment g_dvp_frame_count but won't swap buffers.
   */

  /* Wait for exactly 1 frame — same as camera grab */

  frame_start = g_dvp_frame_count;
  timeout_ms  = 5000;

  syslog(LOG_INFO,
         "[camera] still: waiting for 1 frame (timeout %d ms)...\n",
         timeout_ms);

  while (timeout_ms > 0)
    {
      if (g_dvp_frame_count > frame_start)
        {
          break;
        }

      up_udelay(1000);
      timeout_ms--;
    }

  if (g_dvp_frame_count <= frame_start)
    {
      syslog(LOG_ERR,
             "[camera] still: TIMEOUT — no frame in 5s "
             "(VSYNC=%lu FRAME=%lu)\n",
             (unsigned long)g_dvp_vsync_count,
             (unsigned long)g_dvp_frame_count);
      ret = -ETIMEDOUT;
      goto cleanup_irq;
    }

  /* ============================================================
   * STOP DVP IMMEDIATELY — freeze the PSRAM buffer.
   * This is the key difference from preview: DVP is stopped BEFORE
   * we read the buffer, so no concurrent overwrite can occur.
   * ============================================================ */

  dvp_irq_detach();
  dvp_ctrl_deconfig();

  /* Determine which buf was written (always buf[0] in single-buffer mode) */

  buf_idx = 0;
  buf = g_camera_buf[buf_idx];

  syslog(LOG_INFO,
         "[camera] still: DVP stopped — frame frozen in buf[%d] @ 0x%08lX\n",
         buf_idx, (unsigned long)(uintptr_t)buf);

  /* Log first 32 bytes for format verification */

  syslog(LOG_INFO,
         "[camera] still: first 32 bytes of frozen frame:\n");
  syslog(LOG_INFO,
         "  %02X %02X %02X %02X %02X %02X %02X %02X "
         "%02X %02X %02X %02X %02X %02X %02X %02X\n",
         buf[0],  buf[1],  buf[2],  buf[3],
         buf[4],  buf[5],  buf[6],  buf[7],
         buf[8],  buf[9],  buf[10], buf[11],
         buf[12], buf[13], buf[14], buf[15]);
  syslog(LOG_INFO,
         "  %02X %02X %02X %02X %02X %02X %02X %02X "
         "%02X %02X %02X %02X %02X %02X %02X %02X\n",
         buf[16], buf[17], buf[18], buf[19],
         buf[20], buf[21], buf[22], buf[23],
         buf[24], buf[25], buf[26], buf[27],
         buf[28], buf[29], buf[30], buf[31]);

  /* Downscale UYVY → RGB565 into preview buffer */

  uyvy_to_rgb565_scaled((const uint8_t *)(uintptr_t)buf,
                        (uint8_t *)preview_buf,
                        CAMERA_HRES, CAMERA_VRES,
                        PREVIEW_W, PREVIEW_H);

  /* Initialize LCD and blit the frozen frame */

  ret = bk7258_lcd_preview_init();
  if (ret < 0)
    {
      syslog(LOG_ERR, "[camera] still: LCD init failed: %d\n", ret);
      goto done;
    }

  bk7258_lcd_blit_rgb565(panel, 0, 0, PREVIEW_W, PREVIEW_H,
                          (const uint8_t *)preview_buf);

  syslog(LOG_INFO,
         "[camera] still: FROZEN frame displayed on panel %d (%s). "
         "Screen will hold this image.\n",
         panel, panel == 1 ? "right" : "left");

  return 0;

cleanup_irq:
  dvp_irq_detach();
cleanup_ctrl:
  dvp_ctrl_deconfig();
done:
  return ret;
}

