if (status & YUV_BUF_INT_YUV_ARV)
  {
    g_dvp_frame_count++;

    /* Ping-pong buffer switch:
     * g_write_idx  — buffer DVP just finished writing
     * g_ready_idx  — buffer waiting for consumer (-1 if none)
     * g_consume_idx — buffer consumer is reading (-1 if idle)
     *
     * Safe switch: move g_write_idx to the other buffer ONLY if
     * that buffer is not being consumed (g_consume_idx).
     * em_base update is safe here: YUV_ARV fires after DMA completes;
     * next VSYNC (start of next frame) comes later, so the new em_base
     * is latched before the next DMA begins.
     */

    if (g_stream_active)
      {
        int just_written = g_write_idx;
        int next_write   = 1 - just_written;

        if (g_ready_idx < 0 && next_write != g_consume_idx)
          {
            /* Normal case: hand off completed frame to consumer,
             * switch DVP to the other buffer.
             */

            g_ready_idx = just_written;
            g_write_idx = next_write;
            g_pingpong_count++;

            /* Update em_base for next frame — MUST happen before
             * the next VSYNC so DMA uses the new address.
