/* [D] Feed FIFO with configurable burst size.
 *
 * g_spi_burst=1 (default): per-byte polling, matches ARMino
 *   spi_id_write_bytes_common exactly:
 *     for (i = 0; i < size; i++) {
 *       BK_WHILE (!spi_hal_is_tx_fifo_wr_ready(hal));
 *       spi_hal_write_byte(hal, buf[i]);
 *     }
 *
 * g_spi_burst>1: poll once, then write up to g_spi_burst bytes
 *   without re-checking tx_fifo_wr_ready.  Faster but risks FIFO
 *   overflow if SPI clock is too slow relative to CPU write rate.
 *   burst=48 was the original working implementation (verified at
 *   2 MHz SPI, clk_div=12).  Use "lcdtest burst <n>" to tune.
 */

size_t i;

for (i = 0; i < chunk; )
  {
    size_t burst = chunk - i;
    size_t b;

    if (burst > g_spi_burst)
      {
        burst = g_spi_burst;
      }

    /* Wait for FIFO ready (one check per burst) */

    poll_cnt = SPI_POLL_TIMEOUT;

    while (!(getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE)) &
             SPI_INT_TX_FIFO_WR_READY))
      {
        if (--poll_cnt == 0)
          {
            size_t done = (size_t)(p - data) + i;

            st = getreg32(SPI_REG_INT_STATUS(BK7258_SPI1_BASE));

            syslog(LOG_ERR,
                   "[lcd] SPI TX FIFO timeout, "
                   "INT_STATUS=0x%08lx sent=%lu/%lu "
                   "total_done=%lu/%lu\n",
                   (unsigned long)st,
                   (unsigned long)i,
                   (unsigned long)chunk,
                   (unsigned long)done,
                   (unsigned long)len);
            cfg = getreg32(SPI_REG_CFG(BK7258_SPI1_BASE));
            cfg &= ~SPI_CFG_TX_EN_BIT;
            putreg32(cfg, SPI_REG_CFG(BK7258_SPI1_BASE));
            lcd_spi_pins_to_gpio();
            if (sent_out != NULL)
              {
                *sent_out = done;
              }

            return -ETIMEDOUT;
          }
      }

    /* Write burst bytes to FIFO (no per-byte ready check) */

    for (b = 0; b < burst; b++)
      {
        putreg32(p[i + b], SPI_REG_DATA(BK7258_SPI1_BASE));
      }

    i += burst;
  }

