 * Name: lcdtest_burst
 *
 * Description:
 *   Set SPI FIFO burst write count at runtime.
 *   burst=1 (default): per-byte tx_fifo_wr_ready polling (safe, slow).
 *   burst>1: poll once, then write N bytes to FIFO without re-checking.
 *   Range: 1..48 (FIFO depth).
 *
 * Usage: lcdtest burst <n>
 *
 ****************************************************************************/

static int lcdtest_burst(int argc, char *argv[])
{
  uint32_t n;

  if (argc < 3)
    {
      syslog(LOG_INFO,
             "[burst] current: %lu  (1=per-byte, >1=batch write)\n",
             (unsigned long)g_spi_burst);
      syslog(LOG_INFO, "[burst] usage: lcdtest burst <n>  (1..48)\n");
      return 0;
    }

  n = (uint32_t)atoi(argv[2]);
  if (n < 1)
    {
      n = 1;
    }

  if (n > 48)
    {
      n = 48;
    }

  g_spi_burst = n;

  syslog(LOG_INFO,
         "[burst] set to %lu  (FIFO depth=48, "
         "per-byte=%s)\n",
         (unsigned long)n,
         (n == 1) ? "yes (safe)" : "no (batch, risk of overflow)");

  return 0;
}

input.new_string:
 * Name: lcdtest_burst
 *
 * Description:
 *   Set SPI FIFO burst write count at runtime.
 *   Accepted values: 1, 16, 32, 48 (hardware tx_fifo_int_level thresholds).
 *   burst=1 (default): per-byte tx_fifo_wr_ready polling (safe, slow).
 *   burst=16/32/48: tx_fifo_int level polling, then batch write.
 *
 *   Updates CTRL bits[1:0] (tx_fifo_int_level) and bit6 (tx_fifo_int_en)
 *   at runtime.  Readback verifies the write.
 *
 * Usage: lcdtest burst <1|16|32|48>
 *
 ****************************************************************************/

static int lcdtest_burst(int argc, char *argv[])
{
  uint32_t n;
  uint32_t level;
  uint32_t ctrl;

  if (argc < 3)
    {
      const char *mode = (g_spi_burst <= 1) ? "per-byte tx_fifo_wr_ready" :
                          "tx_fifo_int level polling";
      syslog(LOG_INFO,
             "[burst] current: %lu  (%s)\n",
             (unsigned long)g_spi_burst, mode);
      syslog(LOG_INFO,
             "[burst] usage: lcdtest burst <1|16|32|48>\n");
      syslog(LOG_INFO,
             "[burst]   1  = per-byte polling (safe)\n");
      syslog(LOG_INFO,
             "[burst]  16  = tx_fifo_int level 1 (16 empty slots)\n");
      syslog(LOG_INFO,
             "[burst]  32  = tx_fifo_int level 2 (32 empty slots)\n");
      syslog(LOG_INFO,
             "[burst]  48  = tx_fifo_int level 3 (48 empty slots)\n");
      return 0;
    }

  n = (uint32_t)atoi(argv[2]);

  /* Accept only 1, 16, 32, 48 */

  if (n == 1 || n == 16 || n == 32 || n == 48)
    {
      g_spi_burst = n;
    }
  else
    {
      syslog(LOG_ERR,
             "[burst] invalid value %lu.  Accepted: 1, 16, 32, 48\n",
             (unsigned long)n);
      return -EINVAL;
    }

  /* Update CTRL tx_fifo_int_level (bits[1:0]) and tx_fifo_int_en (bit6) */

  level = burst_to_fifo_level(n);

  ctrl = getreg32(SPI_REG_CTRL(BK7258_SPI1_BASE));
  ctrl &= ~(SPI_CTRL_TX_FIFO_INT_LVL_MASK << SPI_CTRL_TX_FIFO_INT_LVL_SHIFT);
  ctrl &= ~(1u << 6);  /* clear tx_fifo_int_en */

  if (n > 1)
    {
      ctrl |= (level << SPI_CTRL_TX_FIFO_INT_LVL_SHIFT);
      ctrl |= (1u << 6);  /* tx_fifo_int_en */
    }

  putreg32(ctrl, SPI_REG_CTRL(BK7258_SPI1_BASE));

  /* Readback verify */

  uint32_t readback = getreg32(SPI_REG_CTRL(BK7258_SPI1_BASE));
  uint32_t rb_level = (readback >> SPI_CTRL_TX_FIFO_INT_LVL_SHIFT) &
                       SPI_CTRL_TX_FIFO_INT_LVL_MASK;
  uint32_t rb_int_en = (readback >> 6) & 1;

  syslog(LOG_INFO,
         "[burst] set to %lu  level=%lu  "
         "CTRL=0x%08lx  readback level=%lu int_en=%lu %s\n",
         (unsigned long)n,
         (unsigned long)level,
         (unsigned long)readback,
         (unsigned long)rb_level,
         (unsigned long)rb_int_en,
         (rb_level == level && rb_int_en == (n > 1 ? 1u : 0u)) ?
           "OK" : "MISMATCH!");

  return 0;
}

